    const ch = $('#copyHook', el); if (ch) ch.onclick = () => { navigator.clipboard.writeText(w.webhookUrl).then(() => toast('URL copied'), () => toast('Copy failed: select the URL and copy it', 'bad')); };
    const wt = $('#waTest', el); if (wt) wt.onclick = () => { const tt = store.templates().find((x) => x.status === 'APPROVED' && !varCount(x)); if (!CFG.demo && !tt) { toast('A test needs an approved template without blanks, such as hello_world. Sync templates first.', 'bad'); return; } act(() => store.testSend(tt, []), () => toast(CFG.demo ? 'Test message simulated. ' + DEMO_ONLY : 'Test message sent to ' + (store.settings().business.phone || 'your number'), 'good')); };
    const wr = $('#waRefresh', el); if (wr) wr.onclick = () => act(() => store.refreshNumber(), () => { toast('Number details refreshed' + (CFG.demo ? ' (simulated)' : ''), 'good'); re(); });
    const wd = $('#waDisconnect', el); if (wd) wd.onclick = async () => { if (await confirmDialog('Disconnect this number?', 'Campaigns stop and replies no longer arrive here until you connect again. The number and its history at Meta stay yours.', 'Disconnect', true)) act(() => store.disconnectNumber(), () => { store.log('disconnected WhatsApp number', w.phone); toast('Number disconnected'); re(); }); };
