  // Embedded Signup, live: loads Meta's SDK only when needed, opens the pop-up with the app and configuration IDs
  // from WB_CONFIG, and resolves with { code, wabaId, phoneNumberId }. The code is exchanged on the server
  // (n8n wa_signup workflow, which holds the app secret); the browser never sees a token.
  // Hand-off for the data layer: store.connectWithMeta(result) if it exists, else window.WB_ON_META_SIGNUP(result).
  function loadFbSdk(appId) {
    if (window.FB) return Promise.resolve(window.FB);
    return new Promise((resolve, reject) => {
      window.fbAsyncInit = () => { window.FB.init({ appId, autoLogAppEvents: true, xfbml: false, version: 'v21.0' }); resolve(window.FB); };
      const s = document.createElement('script'); s.src = 'https://connect.facebook.net/en_US/sdk.js'; s.async = true; s.defer = true; s.crossOrigin = 'anonymous';
      s.onerror = () => reject(new Error('Meta\'s sign-in script did not load. Check the connection or an ad blocker and try again.'));
      document.head.appendChild(s);
    });
  }
  /* Meta's pop-up talks from these two origins only; anything else (a look-alike host, another frame) is ignored */
  W.isMetaOrigin = (o) => o === 'https://www.facebook.com' || o === 'https://web.facebook.com';
  function startEmbeddedSignup() {
    const appId = CFG.metaAppId, configId = CFG.metaConfigId;
    if (!appId || !configId || /^__/.test(appId + configId)) return Promise.reject(new Error('Connect with Meta is not set up on this installation yet. Use Connect manually instead.'));
    return loadFbSdk(appId).then((FB) => new Promise((resolve, reject) => {
      let session = {};
      const onMsg = (e) => { if (!W.isMetaOrigin(e.origin)) return; try { const d = typeof e.data === 'string' ? JSON.parse(e.data) : e.data; if (d && d.type === 'WA_EMBEDDED_SIGNUP') { if (d.event === 'FINISH' || d.event === 'FINISH_ONLY_WABA') session = { wabaId: d.data.waba_id, phoneNumberId: d.data.phone_number_id }; else if (d.event === 'CANCEL') session = { cancelledAt: d.data && d.data.current_step }; } } catch {} };
      window.addEventListener('message', onMsg);
      FB.login((resp) => { window.removeEventListener('message', onMsg); const code = resp && resp.authResponse && resp.authResponse.code; if (!code) { reject(new Error(session.cancelledAt ? 'The Meta window was closed before the number was connected.' : 'Meta did not confirm the connection.')); return; } resolve({ code, ...session }); },
        { config_id: configId, response_type: 'code', override_default_response_type: true, extras: { setup: {}, featureType: '', sessionInfoVersion: '3' } });
    }));
  }
  // the demo walks through what Meta asks; live opens the real pop-up
  function metaSignupDialog(w, done) {
    const STEPS = [['Log in to Facebook', 'Use the account that manages your business page.'], ['Choose or create a business', 'Your Meta Business portfolio. Business verification can be done later.'], ['Choose or create a WhatsApp Business Account', 'This account owns the number and pays Meta for messages.'], ['Add and verify the number', 'Enter the number, pick your display name, confirm a code by SMS or call.'], ['Add a payment method', 'Meta charges this card for delivered messages. You can add it later in WhatsApp Manager.']];
    let step = 0, running = false;
    const bg = modal('', { narrow: true });
    const draw = () => {
      $('.modal', bg).innerHTML = `<div class="m-head"><div><h2>Connect with Meta</h2><p>${running ? 'Meta\'s window is open. Finish the steps there; this page updates when you are done.' : 'A Meta window opens and asks for the following. Nothing is stored here until Meta confirms.'}</p></div><button class="icon-btn" data-close aria-label="Close">${icon('x')}</button></div><div class="m-body">
        <ol class="list" style="margin:0;padding:0;list-style:none">${STEPS.map(([t, h], i) => `<li class="row" style="flex-wrap:nowrap;align-items:flex-start"><i class="avatar sm" style="${running && i < step ? 'background:var(--accent);border-color:var(--accent);color:var(--accent-ink)' : running && i === step ? 'border-color:var(--accent);color:var(--accent)' : ''}">${running && i < step ? icon('check', 'sm') : i + 1}</i><div><b>${t}</b><div class="small muted">${h}</div></div></li>`).join('')}</ol>
        ${running ? `<div class="bar" style="margin-top:14px"><i style="width:${(step / STEPS.length) * 100}%"></i></div>` : notice('plain', 'You keep full ownership of the number and the Meta account. WhatsApp Blaster receives permission to send and read messages on this number only, and you can remove it in Meta Business Settings at any time.')}
        <p class="small muted" style="margin-top:10px">Meta app ${esc(CFG.metaAppId || 'not set')}, configuration ${esc(CFG.metaConfigId || 'not set')}${CFG.demo ? '. Demo: the window is simulated and Meta is not contacted.' : ''}</p>
        </div><div class="foot"><button class="btn" id="mc">Cancel</button>${running ? '' : `<button class="btn primary" id="mk">${icon('meta')}Continue to Meta</button>`}</div>`;
      $('[data-close]', bg).onclick = closeModal; $('#mc', bg).onclick = closeModal;
      // live: prefer boot.js (window.WB_ES, the dev agent's launcher, which also handles Meta's two-step PIN) with the
      // live store; fall back to this file's own launcher plus store.connectWithMeta / window.WB_ON_META_SIGNUP
      const askPin = () => new Promise((resolve) => { const pb = dialog({ title: 'Enter the number\'s two-step PIN', sub: 'This number already has a six-digit PIN set in WhatsApp. Meta needs it to move the number here.', narrow: true, body: `<div class="field"><label for="waPin">Six-digit PIN</label><input class="input mono" id="waPin" inputmode="numeric" maxlength="6" autocomplete="one-time-code"></div>`, foot: `<button class="btn" data-c>Cancel</button><button class="btn primary" data-k>Continue</button>` }); $('[data-close]', pb).onclick = $('[data-c]', pb).onclick = () => { closeModal(); resolve(null); }; $('[data-k]', pb).onclick = () => { const v = $('#waPin', pb).value.replace(/\D/g, ''); if (v.length !== 6) { $('#waPin', pb).classList.add('invalid'); return; } closeModal(); resolve(v); }; });
      const liveConnect = () => { const ls = window.WB_STORE || store; if (window.WB_ES && window.WB_ES.connectWithFacebook && ls.connectNumber) return window.WB_ES.connectWithFacebook(ls, { askPin });
        return startEmbeddedSignup().then((res) => { const hand = ls.connectNumber ? (r) => ls.connectNumber({ code: r.code, waba_id: r.wabaId, phone_number_id: r.phoneNumberId }) : ls.connectWithMeta || window.WB_ON_META_SIGNUP; if (!hand) throw new Error('Meta confirmed, but this installation cannot finish the connection yet. Contact support.'); return hand(res); }); };
      const mk = $('#mk', bg); if (mk && !CFG.demo) mk.onclick = () => { running = true; step = 0; draw();
        liveConnect().then(() => { closeModal(); toast('Number connected', 'good'); done(); }, (e) => { if ($('.modal', bg) && $('.modal', bg).isConnected) { running = false; draw(); } toast(e.message || 'Connecting with Meta failed', 'bad'); }); };
      else if (mk) mk.onclick = () => { running = true; draw(); const tick = () => { if (!$('.modal', bg).isConnected) return; step++; if (step > STEPS.length) { store.connectSimulated(); store.log('connected WhatsApp number', w.phone); closeModal(); toast(CFG.demo ? 'Number connected (simulated). ' + DEMO_ONLY : 'Number connected. Welcome aboard.', 'good'); done(); return; } draw(); setTimeout(tick, 650); }; setTimeout(tick, 650); };
    };
    draw(); W.focusFirst(bg);
  }
  function connectDialog(w, done) {
    const bg = dialog({ title: 'Connect a number manually', sub: 'For businesses that already have a Meta app with a system-user token. Most people should use Connect with Meta instead.', wide: true, body: `${notice('info', 'You need a Meta Business account, a WhatsApp Business Account with a phone number that is not used in the WhatsApp app, and a permanent system-user token with the permissions whatsapp_business_messaging and whatsapp_business_management. The values below are in Meta Business Settings and in the app\'s WhatsApp, API Setup page.')}
      <div class="grid2" style="margin-top:14px"><div class="field"><label for="cPn">Phone number ID</label><input class="input mono" id="cPn" value="${esc(w.phoneNumberId || '')}" placeholder="15 to 17 digits"></div><div class="field"><label for="cWaba">WhatsApp Business Account ID</label><input class="input mono" id="cWaba" value="${esc(w.wabaId || '')}"></div>
      <div class="field"><label for="cTok">Permanent access token</label><input class="input" type="password" id="cTok" placeholder="${w.tokenSaved ? 'Saved; paste to replace' : 'EAA...'}" autocomplete="off"></div><div class="field"><label for="cSec">App secret, for signed webhooks</label><input class="input" type="password" id="cSec" placeholder="${w.appSecretSaved ? 'Saved; paste to replace' : '32 characters'}" autocomplete="off"></div>
      <div class="field"><label for="cVer">Verify token, you choose it</label><input class="input mono" id="cVer" value="${esc(w.verifyToken || '')}"></div><div class="field"><label for="cName">Display name, as approved by Meta</label><input class="input" id="cName" value="${esc(w.displayName || '')}"></div></div>
      <p class="small muted" style="margin-top:12px">${icon('lock', 'sm')} Tokens and secrets are stored encrypted on the server and never shown again. Connecting checks the token with Meta and reads the number's quality rating and limit.</p>`, foot: `<button class="btn" id="cc">Cancel</button><button class="btn primary" id="ck">Connect and test</button>` });
    $('#cc', bg).onclick = closeModal;
    $('#ck', bg).onclick = () => { const pn = $('#cPn', bg).value.replace(/\D/g, ''), waba = $('#cWaba', bg).value.replace(/\D/g, ''), tok = $('#cTok', bg).value.trim(), sec = $('#cSec', bg).value.trim(), ver = $('#cVer', bg).value.trim(); const bad = [];
      if (pn.length < 10) bad.push('phone number ID'); if (waba.length < 10) bad.push('WhatsApp Business Account ID'); if (!tok && !w.tokenSaved) bad.push('access token'); if (!ver) bad.push('verify token'); if (bad.length) { toast('Check: ' + bad.join(', '), 'bad'); return; }
      act(() => store.connectManual({ phoneNumberId: pn, wabaId: waba, token: tok, appSecret: sec, verifyToken: ver, displayName: $('#cName', bg).value.trim() }), () => { store.log('updated WhatsApp connection', 'number ending ' + pn.slice(-4)); closeModal(); toast(CFG.demo ? 'Connection recorded (demo). Live, the token is verified with Meta now.' : 'Number details saved', 'good'); done(); }); };
  }

  // ================= BOT (version 2, no nav entry) =================
  VIEWS.bot = function renderBot(el) {
    const b = store.settings().bot;
    el.innerHTML = head('Auto-replies', 'Planned for a later version. The settings below are kept so nothing is lost, but no bot answers on your number in version 1.') + notice('info', 'Version 1 has no bot: every incoming message lands in the Inbox for your team. Auto-replies and AI answers are on the roadmap.') +
      `<div class="grid2" style="margin-top:16px">${panel('Greeting and hand-over', `<div class="stack"><div class="field"><label for="bGreet">Greeting</label><input class="input" id="bGreet" value="${esc(b.greeting)}" disabled></div><div class="field"><label for="bHand">Hand-over text</label><input class="input" id="bHand" value="${esc(b.handoff)}" disabled></div></div>`)}${panel('Menu and FAQ', `<div class="list">${b.menu.map((m) => `<div><b>${esc(m.title)}</b><div class="small muted">${esc(m.answer || 'Hands over to the team')}</div></div>`).join('')}${b.faq.map((f) => `<div><b>${esc(f.q)}</b><div class="small muted">${esc(f.a)}</div></div>`).join('')}</div>`)}</div>`;
  };

