  go(VIEWS[hash] ? hash : 'dash');
  $('#whoAvatar').textContent = initials(me().name); $('#whoName').textContent = me().name; $('#whoRole').textContent = ROLES[me().role] || me().role; $('#orgName').textContent = store.settings().business.name;
  if (!CFG.demo) { $('#demoPill').hidden = true; $('#railFoot').textContent = 'Live workspace'; const who = $('#whoName'); const so = window.WB_STORE && window.WB_STORE.signOut; if (who && so) { const b = document.createElement('button'); b.className = 'btn ghost sm'; b.id = 'signOutBtn'; b.textContent = 'Sign out'; b.onclick = () => so(); who.parentNode.appendChild(b); } }
